#!/usr/bin/env python3
"""Generate proven outbound request adaptations from one root parameter table."""
import argparse
import json
from pathlib import Path
import subprocess

ROOT = Path(__file__).resolve().parents[1]


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--check', action='store_true')
    args = parser.parse_args()
    config = json.loads((ROOT / 'upstream-request-adaptations.json').read_text())
    lines = [
        '// Code generated by tools/generate_upstream_request_adaptations.py; DO NOT EDIT.',
        'package service',
        '',
        'var upstreamImageEditsMultipartHosts = map[string]bool{',
    ]
    for host in config['image_edits_multipart_hosts']:
        lines.append('\t' + json.dumps(host) + ': true,')
    lines.append('}')
    lines += ['', 'var claudeOpus55LegacyThinking = map[string]claudeLegacyThinkingAdaptation{']
    for mode, rule in config['claude_opus55_legacy_thinking'].items():
        lines.append('\t' + json.dumps(mode) + ': {Type: ' + json.dumps(rule['type']) +
                     ', Effort: ' + json.dumps(rule['effort']) + '},')
    lines.append('}')
    output = subprocess.check_output(['gofmt'], input='\n'.join(lines) + '\n', text=True)
    destination = ROOT / 'backend/internal/service/upstream_request_adaptations_gen_gotocc.go'
    if args.check:
        if destination.read_text() != output:
            raise SystemExit('upstream request adaptation parameters are out of sync')
    else:
        destination.write_text(output)


if __name__ == '__main__':
    main()
